144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        validateRequiredFields(ownerFieldsDto);
146	        LocalDate registrationDate = toBusinessDay(
147	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
148	        rejectDailyLimitReached(registrationDate);
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        String address = normalizeAddress(ownerFieldsDto.getAddress());
152	        owner.setAddress(address);
153	        rejectCityAtCapacity(owner.getCity());
154	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
155	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
156	        } else {
157	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
158	        }
159	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
160	        rejectDuplicateTelephone(telephone);
161	        owner.setTelephone(telephone);
162	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        owner.setRegistrationDate(registrationDate);
164	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
165	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
166	        this.clinicService.saveOwner(owner);
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
